SELECT count(*) AS would_add, count(DISTINCT p.id) AS products
FROM photo
JOIN "Product" p ON p.handle = photo.handle
WHERE NOT EXISTS (SELECT 1 FROM "ProductImage" i WHERE i."productId" = p.id AND i.url = photo.url);

