INSERT INTO "ProductImage" (id, "productId", url, "altText", color, position)
SELECT gen_random_uuid(), p.id, photo.url, photo.alt_text, photo.color,
       COALESCE((SELECT max(i.position) FROM "ProductImage" i WHERE i."productId" = p.id), -1) + 1 + photo.ord
FROM photo
JOIN "Product" p ON p.handle = photo.handle
WHERE NOT EXISTS (SELECT 1 FROM "ProductImage" i WHERE i."productId" = p.id AND i.url = photo.url);
